export const STATION_CODE_BY_NAME = Object.fromEntries(STATIONS.map((station) => [station.name, station.code]));
export const STATION_NAME_BY_CODE = Object.fromEntries(STATIONS.map((station) => [station.code, station.name]));
export const STATION_BY_CODE = Object.fromEntries(STATIONS.map((station) => [station.code, station]));
export const STATIONS_BY_CITY = STATIONS.reduce((acc, station) => {
  const city = station.cityName || station.name;
  if (!acc[city]) acc[city] = [];
  acc[city].push(station);
  return acc;
}, {});

